import sys
import os
from pathlib import Path
from PyQt6.QtGui import QIcon, QPixmap
from PyQt6.QtCore import QByteArray

ICON_BASE64 = ""

def get_app_icon() -> QIcon:
    # 1. Verifica _MEIPASS (PyInstaller bundle)
    if hasattr(sys, "_MEIPASS"):
        p = Path(sys._MEIPASS) / "icon.ico"
        if p.exists():
            return QIcon(str(p))

    # 2. Verifica pasta do executavel
    exe_p = Path(sys.executable).parent / "icon.ico"
    if exe_p.exists():
        return QIcon(str(exe_p))

    # 3. Verifica pasta do script atual
    curr_p = Path(__file__).parent / "icon.ico"
    if curr_p.exists():
        return QIcon(str(curr_p))

    # 4. Verifica C:\Utilitario
    base_p = Path("C:/Utilitario/icon.ico")
    if base_p.exists():
        return QIcon(str(base_p))

    # 5. Fallback permanente embutido via Base64
    pixmap = QPixmap()
    pixmap.loadFromData(QByteArray.fromBase64(ICON_BASE64.encode("ascii")))
    if not pixmap.isNull():
        return QIcon(pixmap)

    return QIcon()
